def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 3]
    for r, c in points:
        top, bottom = r - 2, r + 2
        for x in range(c - 2, c + 3):
            if 0 <= top < h and 0 <= x < w:
                out[top][x] = 5
            if 0 <= bottom < h and 0 <= x < w:
                out[bottom][x] = 8
        if 0 <= r - 1 < h and 0 <= c < w:
            out[r - 1][c] = 5
        for y in range(r - 1, r + 2):
            if 0 <= y < h:
                for x in (c - 2, c + 2):
                    if 0 <= x < w:
                        out[y][x] = 2
        if 0 <= bottom < h:
            for x in range(w):
                if not (c - 2 <= x <= c + 2):
                    out[bottom][x] = 2
    return out
